function buildReport(){var s=testState.site,o=[];o.push('=== Hs \u7AD9\u6E90\u5168\u5957\u6D4B\u8BD5\u62A5\u544A ===','\u65F6\u95F4\uFF1A'+new Date().toLocaleString(),'\u7AD9\u6E90\uFF1A'+(s.name||'')+' ('+s.key+')','\u63A5\u53E3\uFF1A'+s.api,'\u7ED3\u679C\uFF1A'+testState.summary,'','--- \u6D4B\u8BD5\u6B65\u9AA4 ---');testState.results.forEach(function(x){o.push((x.ok?'[\u2705] ':'[\u274C] ')+x.name+(x.ms!=null?' '+x.ms+'ms':''));if(x.summary)o.push('    '+x.summary);if(x.raw)String(x.raw).split('\\n').forEach(function(l){o.push('    '+l)});o.push('')});return o.join('\\n')}
function safeName(v){return String(v||'site').replace(/[\\\\/:*?"<>|]/g,'_').slice(0,60)}
